INSERT INTO "MaterialPreset" (
  "id", "key", "nombreCanonico", "descripcionCorta", "familia", "subfamilia",
  "tipoTecnico", "templateId", "iconKind", "aliasDisponiblesJson", "usosRecomendadosJson",
  "procesosCompatiblesJson", "advertenciasJson", "orden", "createdAt", "updatedAt"
)
SELECT
  md5('grafo-catalogo-material:' || (dato->>'key'))::uuid,
  dato->>'key', dato->>'nombreCanonico', dato->>'descripcionCorta',
  (dato->>'familia')::"FamiliaMateriaPrima", (dato->>'subfamilia')::"SubfamiliaMateriaPrima",
  dato->>'tipoTecnico', dato->>'templateId', dato->>'iconKind', dato->'aliasDisponiblesJson',
  dato->'usosRecomendadosJson', dato->'procesosCompatiblesJson', dato->'advertenciasJson',
  (dato->>'orden')::integer, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM grafo_catalogo_materiales
ON CONFLICT ("key") DO NOTHING;

INSERT INTO "MaterialPresetVariante" (
  "id", "presetId", "skuSugerido", "nombreVarianteSugerido", "formato", "espesor", "color",
  "recomendada", "atributosVarianteJson", "unidadStock", "unidadCompra", "precioReferencia",
  "moneda", "orden", "createdAt", "updatedAt"
)
SELECT
  md5('grafo-catalogo-variante:' || p."key" || ':' || (v->>'skuSugerido'))::uuid,
  p."id", v->>'skuSugerido', v->>'nombreVarianteSugerido', v->>'formato',
  (v->>'espesor')::numeric, v->>'color', (v->>'recomendada')::boolean,
  v->'atributosVarianteJson', (v->>'unidadStock')::"UnidadMateriaPrima",
  (v->>'unidadCompra')::"UnidadMateriaPrima", (v->>'precioReferencia')::numeric,
  v->>'moneda', (v->>'orden')::integer, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM grafo_catalogo_materiales c
JOIN "MaterialPreset" p ON p."key" = c.dato->>'key'
CROSS JOIN LATERAL jsonb_array_elements(c.dato->'variantes') AS variantes(v)
ON CONFLICT ("presetId", "skuSugerido") DO NOTHING;

COMMIT;
